add_action( 'manage_product_posts_custom_column', 'perfectpixel_variation_skus_column', 20, 2 );

function perfectpixel_variation_skus_column( $column, $post_id ) {
	if ( 'sku' !== $column ) {
		return;
	}
	$product = wc_get_product( $post_id );
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	$skus = array();
	foreach ( $product->get_children() as $child_id ) {
		$variation = wc_get_product( $child_id );
		if ( $variation ) {
			$sku    = $variation->get_sku( 'edit' );
			$skus[] = '' !== $sku ? esc_html( $sku ) : '[ ]';
		}
	}
	if ( $skus ) {
		echo '<br><small style="color:#646970">' . implode( ', ', $skus ) . '</small>';
	}
}
